import ast,hashlib,importlib.util,json
from pathlib import Path
p=json.loads(Path('proposal.json').read_text()); r=json.load(open('/tmp/r001-contract.json'))
print('jsonschema_available',importlib.util.find_spec('jsonschema') is not None)
if importlib.util.find_spec('jsonschema'):
 import jsonschema
 jsonschema.validate(p['study'],r['study_schema'])
else:
 def check(x,s,path='study'):
  typ=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
  if typ: assert isinstance(x,types[typ]),(path,typ)
  if 'enum' in s: assert x in s['enum'],path
  if 'const' in s: assert x==s['const'],path
  if isinstance(x,dict):
   assert all(k in x for k in s.get('required',[])),path
   if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),path
   for k,v in x.items():
    if k in s.get('properties',{}): check(v,s['properties'][k],path+'.'+k)
  if isinstance(x,list):
   assert len(x)>=s.get('minItems',0),path
   for i,v in enumerate(x): check(v,s.get('items',{}),path+f'[{i}]')
  if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
 check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert len(p['variants'])==4 and len({v['name'] for v in p['variants']})==4
base=ast.parse(Path('history_g3_r0044_centered_native64.py').read_text())
def model(tree): return next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
def methods(tree): return {n.name:ast.dump(n,include_attributes=False) for n in model(tree).body if isinstance(n,ast.FunctionDef)}
base_methods=methods(base)
normalized=[]
for v in p['variants']:
 path=Path(v['file']); source=path.read_text(); tree=ast.parse(source); compile(source,str(path),'exec')
 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 config=ast.literal_eval(config_node.value)
 assert config==v['config'],v['name']
 init=next(n for n in model(tree).body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([n.arg for n in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in config.items(): assert ast.literal_eval(defaults[k])==val,(v['name'],k)
 for name,dump in methods(tree).items():
  if name not in ['__init__','forward']: assert dump==base_methods[name],name
 # Exact inherited auxiliary component reduction.
 orig=next(n for n in base.body if isinstance(n,ast.FunctionDef) and n.name=='_auxiliary_context_components')
 new=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='_auxiliary_context_components')
 assert ast.dump(orig)==ast.dump(new)
 # Compare the factorial sources after removing CONFIG and orientation defaults.
 config_node.value=ast.Constant(value=None)
 for i,n in enumerate(init.args.args[-len(init.args.defaults):]):
  if n.arg in ['parallel_orientation','orthogonal_orientation']: init.args.defaults[i]=ast.Constant(value='factor')
 normalized.append(ast.dump(tree,include_attributes=False))
 print(v['name'],'syntax/config/defaults/inherited-methods PASS',hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1,'Unexpected between-arm source differences'
expected={t['id']:t['source_sha256'] for t in r['context']['history']}
for trial,fn in [('baseline-din','history_baseline_din.py'),('g3-r0044-centered_native64','history_g3_r0044_centered_native64.py'),('g3-r0044-centered_reversed64','history_g3_r0044_centered_reversed64.py')]:
 assert hashlib.sha256(Path(fn).read_bytes()).hexdigest()==expected[trial],trial
 print(trial,'ancestor receipt digest PASS')
print('study schema / reference scope / protocol / common factorial source PASS')
print('torch_available',importlib.util.find_spec('torch') is not None)
PY"

